// JX-PROM-100 integration: --run-control executes JXEX bytes recovered from Pixel ROM.
// JARVIS-X 1e12 logical task / 3D bytecode reference VM (C++17).
// Public demonstration only: no trained ANN, exascale allocation or encrypted checkpointing.
#include <algorithm>
#include <array>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <set>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

namespace jx {
constexpr uint64_t ROWS=1000000ULL, COLS=1000000ULL, TASKS=ROWS*COLS;
constexpr uint64_t AXIS=10000ULL, XY=AXIS*AXIS, TILE=16, VOXELS=4096;
constexpr size_t SUPERFRAME_BYTES=1000*1024, KMAX=64;
constexpr double PI=3.14159265358979323846264338327950288;
using Bytes=std::vector<uint8_t>;
struct Coord {uint16_t x,y,z;};
struct Micro {uint8_t opcode,src,dst,aux;};
static_assert(sizeof(Micro)==4,"four-byte microinstruction");
using Program=std::array<Micro,8>;
enum Op:uint8_t {LOAD=0x11,TRY_DCT=0x20,RAW_FALLBACK=0x21,REVERIFY=0x30,SEAL=0x40,HALT=0xff};
constexpr Program CODE{{
 {LOAD,0,1,0},{TRY_DCT,1,2,4},{TRY_DCT,1,2,16},{TRY_DCT,1,2,64},
 {RAW_FALLBACK,1,2,0},{REVERIFY,2,3,0},{SEAL,3,4,0},{HALT,0,0,0}}};
uint64_t splitmix64(uint64_t n){n+=0x9e3779b97f4a7c15ULL;n=(n^(n>>30))*0xbf58476d1ce4e5b9ULL;n=(n^(n>>27))*0x94d049bb133111ebULL;return n^(n>>31);}
uint32_t crc32(const uint8_t* p,size_t n){uint32_t c=~0u;for(size_t j=0;j<n;j++){c^=p[j];for(int i=0;i<8;i++)c=(c>>1)^(0xedb88320u & (0u-(c&1u)));}return ~c;}
uint32_t crc32(const Bytes& b){return crc32(b.data(),b.size());}
Coord id_to_coord(uint64_t id){if(id>=TASKS)throw std::runtime_error("task id outside 1e12 range");return {uint16_t(id%AXIS),uint16_t((id/AXIS)%AXIS),uint16_t(id/XY)};}
uint64_t coord_to_id(Coord c){if(c.x>=AXIS||c.y>=AXIS||c.z>=AXIS)throw std::runtime_error("tile coordinate outside 1e4 axis");return uint64_t(c.x)+AXIS*uint64_t(c.y)+XY*uint64_t(c.z);}
uint64_t morton42(Coord c){uint64_t ans=0;for(unsigned b=0;b<14;b++){ans|=uint64_t((c.x>>b)&1u)<<(3*b);ans|=uint64_t((c.y>>b)&1u)<<(3*b+1);ans|=uint64_t((c.z>>b)&1u)<<(3*b+2);}return ans;}
Coord demorton42(uint64_t m){Coord c{0,0,0};for(unsigned b=0;b<14;b++){c.x|=uint16_t(((m>>(3*b))&1ULL)<<b);c.y|=uint16_t(((m>>(3*b+1))&1ULL)<<b);c.z|=uint16_t(((m>>(3*b+2))&1ULL)<<b);}return c;}
uint64_t address54(Coord tile,uint8_t vx,uint8_t vy,uint8_t vz){if(vx>=16||vy>=16||vz>=16)throw std::runtime_error("local voxel coordinates outside 16");const uint64_t local=(uint64_t(vz)<<8)|(uint64_t(vy)<<4)|vx;return (morton42(tile)<<12)|local;}
void put8(Bytes& b,uint8_t v){b.push_back(v);}void put16(Bytes&b,uint16_t v){put8(b,v&255);put8(b,(v>>8)&255);}void put32(Bytes&b,uint32_t v){for(int j=0;j<4;j++)put8(b,uint8_t(v>>(8*j)));}void put64(Bytes&b,uint64_t v){for(int j=0;j<8;j++)put8(b,uint8_t(v>>(8*j)));}
void putf(Bytes&b,float f){uint32_t bits;static_assert(sizeof(f)==4,"");std::memcpy(&bits,&f,4);put32(b,bits);}
struct Reader {const Bytes& b;size_t at=0;explicit Reader(const Bytes& in):b(in){}void need(size_t n){if(n>b.size()-at)throw std::runtime_error("truncated binary data");}uint8_t u8(){need(1);return b[at++];}uint16_t u16(){uint16_t v=u8();v|=uint16_t(u8())<<8;return v;}uint32_t u32(){uint32_t v=0;for(int j=0;j<4;j++)v|=uint32_t(u8())<<(8*j);return v;}uint64_t u64(){uint64_t v=0;for(int j=0;j<8;j++)v|=uint64_t(u8())<<(8*j);return v;}float f32(){uint32_t bits=u32();float f;std::memcpy(&f,&bits,4);return f;}};
Bytes control_frame(){Bytes f(SUPERFRAME_BYTES,0);const std::string magic="JXSF1T12";std::copy(magic.begin(),magic.end(),f.begin());auto put_slot=[&](size_t at,uint64_t value,size_t n){for(size_t i=0;i<n;i++)f[at+i]=uint8_t(value>>(8*i));};put_slot(8,1,4);put_slot(16,TASKS,8);put_slot(24,AXIS,4);put_slot(28,TILE,4);put_slot(32,1000,4);put_slot(36,CODE.size(),4);const size_t rom=4096;f[rom]='J';f[rom+1]='X';f[rom+2]='E';f[rom+3]='X';f[rom+4]=uint8_t(CODE.size());for(size_t i=0;i<CODE.size();i++){const size_t p=rom+16+i*4;f[p]=CODE[i].opcode;f[p+1]=CODE[i].src;f[p+2]=CODE[i].dst;f[p+3]=CODE[i].aux;}
 const size_t opt=5120;f[opt]='J';f[opt+1]='X';f[opt+2]='O';f[opt+3]='P';for(unsigned i=0;i<8;i++){f[opt+16+i*4]=uint8_t(0x70+i);}
 uint32_t check=crc32(f.data(),SUPERFRAME_BYTES-4);for(int i=0;i<4;i++)f[SUPERFRAME_BYTES-4+i]=uint8_t(check>>(8*i));return f;}
void validate_control(const Bytes& f){if(f.size()!=SUPERFRAME_BYTES)throw std::runtime_error("control frame must be 1024000 bytes");if(std::memcmp(f.data(),"JXSF1T12",8))throw std::runtime_error("invalid control magic");auto get=[&](size_t at,unsigned n){uint64_t v=0;for(unsigned i=0;i<n;i++)v|=uint64_t(f[at+i])<<(8*i);return v;};if(get(8,4)!=1||get(16,8)!=TASKS||get(24,4)!=AXIS||get(28,4)!=TILE||get(32,4)!=1000||get(36,4)!=CODE.size())throw std::runtime_error("unsupported control frame parameters");if(std::memcmp(f.data()+4096,"JXEX",4)||std::memcmp(f.data()+5120,"JXOP",4))throw std::runtime_error("ROM signatures invalid");for(size_t i=0;i<CODE.size();i++){const size_t p=4096+16+i*4;if(f[p]!=CODE[i].opcode||f[p+1]!=CODE[i].src||f[p+2]!=CODE[i].dst||f[p+3]!=CODE[i].aux)throw std::runtime_error("ROM altered");}if(get(SUPERFRAME_BYTES-4,4)!=crc32(f.data(),SUPERFRAME_BYTES-4))throw std::runtime_error("control frame CRC mismatch");}
Program decode_program(const Bytes& frame){
    validate_control(frame);
    Program ops{};
    for(size_t i=0;i<ops.size();i++){
        const size_t off=4096+16+i*4;
        ops[i]={frame[off],frame[off+1],frame[off+2],frame[off+3]};
    }
    return ops;
}
void save(const std::string& p,const Bytes& b){std::ofstream f(p,std::ios::binary);if(!f||!f.write(reinterpret_cast<const char*>(b.data()),std::streamsize(b.size())))throw std::runtime_error("file write failed: "+p);}
Bytes load(const std::string& p,size_t max){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("file open failed: "+p);auto n=f.tellg();if(n<0||uint64_t(n)>max)throw std::runtime_error("file size exceeds limit");Bytes b(size_t(n),0);f.seekg(0);if(!f.read(reinterpret_cast<char*>(b.data()),std::streamsize(b.size())))throw std::runtime_error("file read failed");return b;}

struct Basis {std::array<std::vector<float>,KMAX> v;std::array<std::array<int,3>,KMAX> f;Basis(){int idx=0;for(int sum=0;sum<20&&idx<int(KMAX);sum++)for(int x=sum;x>=0&&idx<int(KMAX);x--)for(int y=sum-x;y>=0&&idx<int(KMAX);y--){int z=sum-x-y;if(x>=16||y>=16||z>=16)continue;f[size_t(idx++)]={x,y,z};}if(idx!=KMAX)throw std::runtime_error("basis count");for(size_t k=0;k<KMAX;k++){auto [fx,fy,fz]=f[k];auto& row=v[k];row.resize(VOXELS);const double scale=(fx?std::sqrt(2.0/16):0.25)*(fy?std::sqrt(2.0/16):0.25)*(fz?std::sqrt(2.0/16):0.25);for(unsigned z=0;z<16;z++)for(unsigned y=0;y<16;y++)for(unsigned x=0;x<16;x++){row[x+16*y+256*z]=float(scale*std::cos(PI*(x+.5)*fx/16)*std::cos(PI*(y+.5)*fy/16)*std::cos(PI*(z+.5)*fz/16));}}}
};
using Tile=std::array<float,VOXELS>;
Tile synthetic(uint64_t id,const Basis& b){Tile out{};if(id%5==0){for(unsigned i=0;i<VOXELS;i++){uint64_t h=splitmix64(id^uint64_t(i)*0x9e3779b97f4a7c15ULL);out[i]=float(int(h%65536)-32768)/32768.f;}}else {for(unsigned i=0;i<VOXELS;i++)out[i]=30.f*b.v[0][i]+17.f*b.v[1][i]-13.f*b.v[2][i]+7.f*b.v[3][i];}return out;}
struct Quality {double r2=0;unsigned sign_mismatch=0;double mse=0;};
Quality assess(const Tile& input,const Tile& decoded){double sum=0,err=0;for(float x:input)sum+=x;double mean=sum/VOXELS,var=0;Quality q;for(size_t i=0;i<VOXELS;i++){double delta=double(input[i])-decoded[i];err+=delta*delta;double d=input[i]-mean;var+=d*d;if((input[i]<0)!=(decoded[i]<0))q.sign_mismatch++;}q.mse=err/VOXELS;q.r2=var==0?(err==0?1.:0.):1.-err/var;return q;}
struct Record {uint64_t id=0;uint8_t mode=0,k=0;float quality=0;uint32_t sign_mismatch=0,decoded_crc=0;Bytes payload;};
Tile decode(const Record& rec,const Basis& b){Tile out{};if(rec.mode==1){if(rec.k!=4&&rec.k!=16&&rec.k!=64)throw std::runtime_error("illegal K");if(rec.payload.size()!=size_t(rec.k)*4)throw std::runtime_error("invalid coefficient length");Reader r(rec.payload);std::vector<float> coefficients(rec.k);for(auto& c:coefficients)c=r.f32();for(unsigned j=0;j<rec.k;j++)for(size_t i=0;i<VOXELS;i++)out[i]+=coefficients[j]*b.v[j][i];}else if(rec.mode==2){if(rec.k!=0||rec.payload.size()!=VOXELS*4)throw std::runtime_error("invalid raw tile length");Reader r(rec.payload);for(auto& c:out)c=r.f32();}else throw std::runtime_error("unsupported encoding mode");return out;}
uint32_t tile_crc(const Tile& a){Bytes b;b.reserve(VOXELS*4);for(auto f:a)putf(b,f);return crc32(b);}
Record execute_tile(uint64_t id,const Basis& b,unsigned iterations,const Program& program){const Tile orig=synthetic(id,b);Record chosen;chosen.id=id;bool have=false;auto now=std::chrono::steady_clock::now();(void)now;for(const Micro& op:program){if(op.opcode==LOAD){continue;}if(op.opcode==TRY_DCT){if(have)continue;Record candidate;candidate.id=id;candidate.mode=1;candidate.k=op.aux;candidate.payload.reserve(candidate.k*4);for(unsigned j=0;j<candidate.k;j++){double coeff=0;for(size_t i=0;i<VOXELS;i++)coeff+=double(orig[i])*b.v[j][i];putf(candidate.payload,float(coeff));}const Tile restored=decode(candidate,b);Quality q=assess(orig,restored);if(q.r2>=0.98&&q.sign_mismatch==0){chosen=std::move(candidate);chosen.quality=float(q.r2);chosen.sign_mismatch=q.sign_mismatch;have=true;}}else if(op.opcode==RAW_FALLBACK){if(!have){chosen.id=id;chosen.mode=2;chosen.k=0;chosen.payload.reserve(VOXELS*4);for(auto x:orig)putf(chosen.payload,x);chosen.quality=1.0f;have=true;}}else if(op.opcode==REVERIFY){if(!have)throw std::runtime_error("bytecode reached verifier without a plan");for(unsigned j=0;j<iterations;j++){Tile restored=decode(chosen,b);Quality q=assess(orig,restored);if(q.r2<0.98||q.sign_mismatch!=0)throw std::runtime_error("revalidation failed");chosen.quality=float(q.r2);}}else if(op.opcode==SEAL){chosen.decoded_crc=tile_crc(decode(chosen,b));}else if(op.opcode==HALT){return chosen;}else throw std::runtime_error("unknown opcode");}throw std::runtime_error("bytecode missing HALT");}
std::vector<uint64_t> choose_active(unsigned count,uint64_t seed){if(count>4096)throw std::runtime_error("demo limits active tiles to 4096");std::set<uint64_t> selected;for(uint64_t i=0;selected.size()<count;i++)selected.insert(splitmix64(seed+i)%TASKS);return {selected.begin(),selected.end()};}
std::vector<Record> run_parallel(const std::vector<uint64_t>&ids,unsigned workers,unsigned iterations,const Basis& b,const Program& program){std::vector<Record> records(ids.size());std::atomic<size_t> next{0};std::vector<std::thread> pool;workers=std::min<unsigned>(workers,unsigned(ids.size()));if(!workers)return records;for(unsigned w=0;w<workers;w++)pool.emplace_back([&](){for(;;){size_t i=next.fetch_add(1,std::memory_order_relaxed);if(i>=ids.size())return;records[i]=execute_tile(ids[i],b,iterations,program);}});for(auto& t:pool)t.join();return records;}
Bytes serialize(const std::vector<Record>&records,const Bytes& control){validate_control(control);Bytes b;b.reserve(32+records.size()*128);for(char c:std::string("JXAR1T12"))put8(b,uint8_t(c));put32(b,1);put64(b,TASKS);put32(b,uint32_t(records.size()));put32(b,crc32(control));put32(b,0);for(auto& rec:records){put64(b,rec.id);put8(b,rec.mode);put8(b,rec.k);put16(b,0);putf(b,rec.quality);put32(b,rec.sign_mismatch);put32(b,rec.decoded_crc);put32(b,uint32_t(rec.payload.size()));b.insert(b.end(),rec.payload.begin(),rec.payload.end());}put32(b,crc32(b));return b;}
std::vector<Record> deserialize(const Bytes& ar,const Bytes& control,const Basis& basis){validate_control(control);if(ar.size()<36)throw std::runtime_error("archive too small");Reader r(ar);for(char c:std::string("JXAR1T12"))if(r.u8()!=uint8_t(c))throw std::runtime_error("archive magic invalid");if(r.u32()!=1||r.u64()!=TASKS)throw std::runtime_error("archive version or domain invalid");const uint32_t count=r.u32();if(count>4096)throw std::runtime_error("archive record count too large");if(r.u32()!=crc32(control)||r.u32()!=0)throw std::runtime_error("control binding invalid");std::vector<Record> out;out.reserve(count);uint64_t previous=0;for(uint32_t i=0;i<count;i++){Record rec;rec.id=r.u64();rec.mode=r.u8();rec.k=r.u8();if(r.u16()!=0)throw std::runtime_error("unexpected reserved bytes");rec.quality=r.f32();rec.sign_mismatch=r.u32();rec.decoded_crc=r.u32();uint32_t n=r.u32();if(n>VOXELS*4)throw std::runtime_error("record payload too large");r.need(n);rec.payload.assign(ar.begin()+r.at,ar.begin()+r.at+n);r.at+=n;if(rec.id>=TASKS||(i&&rec.id<=previous))throw std::runtime_error("unsorted or out-of-domain task id");previous=rec.id;Tile recovered=decode(rec,basis);if(tile_crc(recovered)!=rec.decoded_crc)throw std::runtime_error("decoded tile CRC mismatch");if(!(rec.quality>=0.98&&rec.quality<=1.00001f)||rec.sign_mismatch)throw std::runtime_error("quality metadata invalid");out.push_back(std::move(rec));}if(r.at!=ar.size()-4)throw std::runtime_error("archive length mismatch");if(r.u32()!=crc32(ar.data(),ar.size()-4))throw std::runtime_error("archive CRC mismatch");return out;}
void preview_ply(const std::vector<Record>&recs,const std::string&path){std::ofstream o(path);if(!o)throw std::runtime_error("PLY open failed");o<<"ply\nformat ascii 1.0\nelement vertex "<<recs.size()<<"\nproperty float x\nproperty float y\nproperty float z\nproperty uchar red\nproperty uchar green\nproperty uchar blue\nend_header\n";for(auto&rec:recs){Coord c=id_to_coord(rec.id);o<<c.x<<' '<<c.y<<' '<<c.z<<' '<<(rec.mode==1?32:250)<<' '<<(rec.mode==1?220:154)<<' '<<(rec.mode==1?255:45)<<'\n';}}
void selftest(){auto check=[](bool ok,const char*name){if(!ok)throw std::runtime_error(std::string("self-test failed: ")+name);};check(TASKS==1000000000000ULL,"logical size");check(AXIS*AXIS*AXIS==TASKS,"cube equivalence");check(coord_to_id({9999,9999,9999})==TASKS-1,"last tile");for(uint64_t id:std::array<uint64_t,6>{{0,1,999999,1000000,100000000,TASKS-1}}){Coord c=id_to_coord(id);check(coord_to_id(c)==id,"tile bijection");check(demorton42(morton42(c)).x==c.x&&demorton42(morton42(c)).y==c.y&&demorton42(morton42(c)).z==c.z,"Morton roundtrip");}check(address54({9999,9999,9999},15,15,15)<(1ULL<<54),"54-bit address");for(uint64_t k=0;k<20000;k++){const auto id=splitmix64(k)%TASKS;const auto coord=id_to_coord(id);const auto back=demorton42(morton42(coord));check(id==coord_to_id(coord)&&coord_to_id(back)==id,"randomized mapping property");}Bytes control=control_frame();check(control.size()==SUPERFRAME_BYTES,"frame size");validate_control(control);Basis basis;auto ops=decode_program(control);auto ids=choose_active(32,1234);auto a=run_parallel(ids,1,2,basis,ops),b=run_parallel(ids,4,2,basis,ops);Bytes aa=serialize(a,control),bb=serialize(b,control);check(aa==bb,"worker deterministic");auto back=deserialize(aa,control,basis);check(back.size()==32,"archive decode");bool saw_compressed=false,saw_raw=false;for(auto&r:back){saw_compressed|=(r.mode==1);saw_raw|=(r.mode==2);}check(saw_compressed&&saw_raw,"adaptive codecs");Bytes broken=aa;broken[broken.size()/2]^=0x3f;bool rejected=false;try{deserialize(broken,control,basis);}catch(...){rejected=true;}check(rejected,"tamper rejection by CRC");Bytes tampered=control;tampered[98765]^=1;rejected=false;try{validate_control(tampered);}catch(...){rejected=true;}check(rejected,"control corruption detection");std::cout<<"SELFTEST PASS: 1e12 mappings, 54-bit addresses, 1024000-byte frame, adaptive 3D, parallel determinism, recovery, CRC rejection\n";}
void usage(){std::cout<<"Usage: jx_mp_1e12 --self-test | --run | --run-control [--active N] [--workers N] [--iterations N] [--seed N] [--control path] [--archive path] [--ply path] | --verify [--control path] [--archive path]\n";}
int main_run(int argc,char**argv){if(argc<=1){usage();return 0;}std::string mode=argv[1],controlpath="control.jxsf",archivepath="tiles.jxar",plypath="active_tiles.ply";unsigned active=128,workers=4,iterations=2;uint64_t seed=42;auto parse=[&](const std::string& s)->uint64_t{size_t pos=0;unsigned long long n=std::stoull(s,&pos,10);if(pos!=s.size())throw std::runtime_error("bad numeric option");return n;};for(int i=2;i<argc;i++){std::string opt=argv[i];if(i+1>=argc)throw std::runtime_error("missing option value");std::string value=argv[++i];if(opt=="--active"){auto n=parse(value);if(n>4096)throw std::runtime_error("active above limit");active=unsigned(n);}else if(opt=="--workers"){auto n=parse(value);if(n>64)throw std::runtime_error("workers above limit");workers=unsigned(n);}else if(opt=="--iterations"){auto n=parse(value);if(n>16)throw std::runtime_error("iterations above limit");iterations=unsigned(n);}else if(opt=="--seed")seed=parse(value);else if(opt=="--control")controlpath=value;else if(opt=="--archive")archivepath=value;else if(opt=="--ply")plypath=value;else throw std::runtime_error("unknown option "+opt);}if(mode=="--self-test"){selftest();return 0;}if(active==0||active>4096||workers==0||workers>64||iterations==0||iterations>16)throw std::runtime_error("out-of-range active/workers/iterations");Basis basis; if(mode=="--run"||mode=="--run-control"){auto ids=choose_active(active,seed);auto control=(mode=="--run-control"?load(controlpath,SUPERFRAME_BYTES):control_frame());auto start=std::chrono::steady_clock::now();auto ops=decode_program(control);auto recs=run_parallel(ids,workers,iterations,basis,ops);double ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();auto archive=serialize(recs,control);save(controlpath,control);save(archivepath,archive);preview_ply(recs,plypath);auto validated=deserialize(archive,control,basis);unsigned compressed=0,raw=0;double min_q=1.,mean_q=0.;for(auto& r:validated){compressed+=(r.mode==1);raw+=(r.mode==2);min_q=std::min(min_q,double(r.quality));mean_q+=r.quality;}mean_q/=validated.size();std::cout<<"logical_tasks="<<TASKS<<" mapped_3d="<<AXIS<<"^3 virtual_voxels="<<(TASKS*VOXELS)<<"\n";std::cout<<"active_tiles="<<recs.size()<<" compressed="<<compressed<<" raw_fallback="<<raw<<" workers="<<workers<<" iterations="<<iterations<<"\n";std::cout<<"mean_r2="<<std::setprecision(9)<<mean_q<<" worst_r2="<<min_q<<" encode_verify_ms="<<std::setprecision(5)<<ms<<"\n";std::cout<<"superframe_bytes="<<control.size()<<" archive_bytes="<<archive.size()<<"\n";return 0;}if(mode=="--verify"){auto control=load(controlpath,SUPERFRAME_BYTES);auto archive=load(archivepath,4096ULL*(VOXELS*4+64)+64);auto recs=deserialize(archive,control,basis);double min_q=1.;for(auto&rec:recs) {Quality q=assess(synthetic(rec.id,basis),decode(rec,basis));if(q.r2<0.98||q.sign_mismatch!=0)throw std::runtime_error("actual decoded quality failed");min_q=std::min(min_q,q.r2);}std::cout<<"VERIFY PASS: records="<<recs.size()<<" min_actual_r2="<<std::setprecision(9)<<min_q<<"\n";return 0;}throw std::runtime_error("unknown command");}
} // namespace jx
int main(int argc,char**argv){try{return jx::main_run(argc,argv);}catch(const std::exception& e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
